//! Cross-check `solve::shift_compare` directly against
//! `tandemmp.drift.corrector._shift_compare` (not just the underlying
//! `scipy.ndimage.shift` primitive) — this exercises the crop
//! (`_float_to_slice`) + RMSE composition exactly as the differential
//! evolution objective uses it.
//!
//! `tests/fixtures/shift_compare_cases.txt` was generated by calling the
//! real Python `_shift_compare` on the `tandemmp-refactor` conda
//! environment. Format:
//!
//! ```text
//! <rows> <cols>
//! <rows*cols baseline_frame values, space-separated>
//! <rows*cols input_frame values, space-separated>
//! <n_cases>
//! <x> <y> <expected_rmse>   (repeated n_cases times)
//! ```

use std::fs;
use std::path::Path;

#[test]
fn shift_compare_matches_python() {
    let path = Path::new(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/shift_compare_cases.txt"
    ));
    let text = fs::read_to_string(path).expect("failed to read shift_compare fixture");
    let mut lines = text.lines();

    let mut header = lines.next().unwrap().split_whitespace();
    let rows: usize = header.next().unwrap().parse().unwrap();
    let cols: usize = header.next().unwrap().parse().unwrap();

    let parse_row = |line: &str| -> Vec<f64> {
        line.split_whitespace()
            .map(|s| s.parse::<f64>().unwrap())
            .collect()
    };

    let baseline = parse_row(lines.next().unwrap());
    let input_frame = parse_row(lines.next().unwrap());
    assert_eq!(baseline.len(), rows * cols);
    assert_eq!(input_frame.len(), rows * cols);

    let n_cases: usize = lines.next().unwrap().trim().parse().unwrap();
    let mut checked = 0;
    for line in lines {
        if line.trim().is_empty() {
            continue;
        }
        let mut parts = line.split_whitespace();
        let x: f64 = parts.next().unwrap().parse().unwrap();
        let y: f64 = parts.next().unwrap().parse().unwrap();
        let expected: f64 = parts.next().unwrap().parse().unwrap();

        let actual = drift_correction::shift_compare(x, y, &input_frame, &baseline, rows, cols);
        assert!(
            (actual - expected).abs() <= 1e-8,
            "x={x} y={y} actual={actual} expected={expected}"
        );
        checked += 1;
    }
    assert_eq!(checked, n_cases);
}
